def cycpattern_check(a, b):
    """Return True if b or any rotation of b is a substring of a."""
    # Validate inputs
    if not isinstance(a, str) or not isinstance(b, str):
        raise TypeError("Both inputs must be strings.")
    if b == "":
        return True
    if len(b) > len(a):
        return False

    bb = b + b
    L = len(b)
    # Check all rotations implicitly via substrings of bb
    for i in range(L):
        rotation = bb[i:i+L]
        if rotation in a:
            return True
    return False
